#!/usr/bin/env node
// run it on any machine and send us the json it writes
//   sleep-watch                 prints what it found on this machine
//   sleep-watch watch           watches till ctrl+c, prints every sleep / wakeup and writes them to sleep-watch-report.json
//   sleep-watch watch suspend   the same, and suspends the machine after 3s (linux with systemd only for now)
const sleep_watch = require('./')
const fs = require('fs')
const { execFileSync, spawn } = require('child_process')

const report = { found: found(), events: [] }
const [command, option] = process.argv.slice(2)

if (command !== 'watch') console.log(JSON.stringify(report.found, null, 2))
else watch()

function watch () {
  setInterval(() => {}, 60000) // keeps it running till ctrl+c
  const on = sleep_watch()
  on({ wakeup, sleep })
  log({ type: 'watching', at: Date.now() })
  if (option === 'suspend') setTimeout(suspend, 3000)
}

async function sleep () {
  log({ type: 'sleep', at: Date.now() })
  await new Promise(resolve => setTimeout(resolve, 1000)) // pretends a bot needs 1s to stop
}

function wakeup ({ gap, at, announced }) { log({ type: 'wakeup', at, gap, announced }) }

function suspend () {
  if (report.found.system !== 'linux-systemd') return log({ type: 'error', at: Date.now(), message: 'suspend only works on linux with systemd for now' })
  spawn('systemctl', ['suspend'], { stdio: 'inherit' })
}

function log (event) {
  report.events.push(event)
  console.log(new Date(event.at).toISOString(), event.type, event.gap ? `gap ${event.gap}ms announced ${event.announced}` : event.message || '')
  fs.writeFileSync('sleep-watch-report.json', JSON.stringify(report, null, 2))
}

function found () {
  return { system: sleep_watch.detect_system(), platform: process.platform, arch: process.arch, node: process.version, tools: { gdbus: has('gdbus'), 'systemd-inhibit': has('systemd-inhibit') } }
}

function has (tool) {
  try {
    execFileSync('which', [tool], { stdio: 'ignore' })
    return true
  } catch {
    return false
  }
}
